// App code: timing, stacking and dismissal.
import type { Example, Motion, MotionState } from "../example.ts"
import { html, type TemplateResult } from "lit-html"

const tones = ["accent", "success", "warning", "danger", "neutral"] as const

export type ToastTone = (typeof tones)[number]

export type ToastProps = {
  message: string
  tone?: ToastTone
  action?: string
  onAction?: () => void
  state?: MotionState
  class?: string
}

// The toast's look only. No motion (toast() adds the open and close motion) and no placement (apps stack and place them).
const look = "flex items-center gap-4 px-4 py-3 rounded-control text-sm shadow-lg"

const rise = "transition-[opacity,transform] duration-normal ease-enter starting:opacity-0 starting:translate-y-2"

const states: Record<MotionState, string> = { open: "", closed: "opacity-0 translate-y-2" }

export const motion: Motion = { duration: "duration.normal" }

// Web Awesome variant brand, success, warning, danger, neutral.
const fills: Record<ToastTone, string> = {
  accent: "bg-accent-strong text-on-fill",
  success: "bg-ok-fg text-on-fill",
  warning: "bg-warn-fg text-on-fill",
  danger: "bg-danger text-on-fill",
  neutral: "bg-fg text-canvas",
}

/** Apps put these classes on their own toast. */
export function toastClass(tone: ToastTone = "neutral"): string {
  return `${look} ${fills[tone]}`
}

/** Apps put these classes on the toast's action button; it takes the toast's text colour. */
export function toastActionClass(): string {
  return "-my-1 shrink-0 rounded-md px-2 py-1 font-semibold underline-offset-2 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent/50 focus-visible:ring-offset-0"
}

export function toast(props: ToastProps): TemplateResult {
  const tone = props.tone ?? "neutral"
  const own = `${toastClass(tone)} ${rise}`
  const stated = props.state === "closed" ? `${own} ${states.closed}` : own
  const classes = props.class === undefined ? stated : `${stated} ${props.class}`
  const role = tone === "danger" ? "alert" : "status"
  return html`<div class=${classes} role=${role}>
    <span>${props.message}</span>
    ${props.action === undefined ? undefined : html`<button type="button" class=${toastActionClass()} @click=${props.onAction}>${props.action}</button>`}
  </div>`
}

/** The gallery draws one cell per tone; add one to `tones` and `fills` and a new cell appears. */
export const variants = { tone: [...tones] }

export const sample = { message: "Photo added to Summer 2026" } satisfies Omit<ToastProps, keyof typeof variants>

export const examples: Example[] = [{ label: "with action", render: () => toast({ ...sample, action: "Undo" }) }]
